import shutil
import openpyxl
import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

# Use the active sheet as the answer sheet; fall back to Sheet2 if needed.
ws = wb.active
vws = vals.active

if vws["D7"].value is None and "Sheet2" in vals.sheetnames:
    ws = wb["Sheet2"]
    vws = vals["Sheet2"]

def norm_date(value):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, (int, float)):
        try:
            return (datetime.datetime(1899, 12, 30) + datetime.timedelta(days=float(value))).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        try:
            return datetime.datetime.fromisoformat(s[:10]).date()
        except Exception:
            pass
    return None

def clean_number(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        s = value.strip()
        try:
            return float(s)
        except Exception:
            return s
    return value

fiscal = vws["D7"].value
target = norm_date(fiscal)

col = None
if target is not None:
    for c in range(1, vws.max_column + 1):
        d = norm_date(vws.cell(row=3, column=c).value)
        if d is not None and d.year == target.year and d.month == target.month:
            col = c
            break

if col is not None:
    d9 = clean_number(vws.cell(row=4, column=col).value)
    d10 = clean_number(vws.cell(row=5, column=col).value)
    d11 = clean_number(vws.cell(row=6, column=col).value)
    d12 = clean_number(vws.cell(row=7, column=col).value)

    ws["D9"] = d9
    ws["D10"] = d10
    ws["D11"] = d11
    ws["D12"] = d12

    print("Fiscal month:", target)
    print("Matched column:", col)
    print("D9:D12:", d9, d10, d11, d12)
else:
    print("No matching month column found for fiscal value:", fiscal)

wb.save(OUT)
